CREATE TABLE IF NOT EXISTS payment_settings (id INTEGER PRIMARY KEY CHECK (id=1), active INTEGER DEFAULT 0, environment TEXT DEFAULT 'test', public_key TEXT, access_token_encrypted TEXT, webhook_secret_encrypted TEXT, pix_enabled INTEGER DEFAULT 1, card_enabled INTEGER DEFAULT 1, boleto_enabled INTEGER DEFAULT 1, updated_by INTEGER, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT, company_id INTEGER NOT NULL, user_id INTEGER NOT NULL, plan_id INTEGER, amount REAL NOT NULL, currency TEXT DEFAULT 'BRL', billing_period TEXT NOT NULL, limits_snapshot_json TEXT NOT NULL, internal_reference TEXT NOT NULL UNIQUE, idempotency_key TEXT NOT NULL UNIQUE, provider TEXT DEFAULT 'mercado_pago', provider_payment_id TEXT, payment_method TEXT, status TEXT NOT NULL DEFAULT 'CREATED', provider_status TEXT, provider_status_detail TEXT, checkout_data_json TEXT DEFAULT '{}', created_at TEXT DEFAULT CURRENT_TIMESTAMP, approved_at TEXT, expires_at TEXT, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS subscription_periods (id INTEGER PRIMARY KEY AUTOINCREMENT, company_id INTEGER NOT NULL, subscription_id INTEGER NOT NULL, plan_id INTEGER, payment_id INTEGER NOT NULL UNIQUE, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, limits_snapshot_json TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payment_events (id INTEGER PRIMARY KEY AUTOINCREMENT, company_id INTEGER NOT NULL, payment_id INTEGER NOT NULL, event_name TEXT NOT NULL, payload_json TEXT DEFAULT '{}', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_payments_company_created ON payments(company_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_payments_company_status ON payments(company_id, status);
CREATE UNIQUE INDEX IF NOT EXISTS idx_payments_provider_id ON payments(provider, provider_payment_id) WHERE provider_payment_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_subscription_periods_company_end ON subscription_periods(company_id, ends_at DESC);
